184	    public ClientService(ClientRepository clients, ProjectRepository projects, ContactRepository contacts,
185	            InvoiceRepository invoices, PaymentRepository payments, Audit audit) {
186	        this.clients = clients;
187	        this.projects = projects;
188	        this.contacts = contacts;
189	        this.invoices = invoices;
190	        this.payments = payments;
191	        this.audit = audit;
192	    }
193	
194	    /** The clients, leaving out archived ones unless they are asked for. */
195	    @Transactional(readOnly = true)
196	    public List<ClientResponse> list(boolean includeArchived) {
197	        List<Client> found = includeArchived ? clients.findAll(Sort.by("id")) : clients.findByArchivedFalseOrderById();
198	        return respond(found);
199	    }
200	
201	    @Transactional(readOnly = true)
202	    public ClientResponse get(Long id) {
203	        return respond(find(id));
204	    }
205	
206	    /** At-a-glance counts of what one client has. */
207	    @Transactional(readOnly = true)
208	    public ClientSummaryResponse summary(Long id) {
209	        if (!clients.existsById(id)) {
210	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
211	        }
212	        return new ClientSummaryResponse(projects.countByClientId(id), contacts.countByClientId(id));
213	    }
214	
215	    /** Adds a client; its email, once trimmed, must not already belong to another client. */
216	    @Transactional
217	    public ClientResponse create(ClientRequest request) {
218	        String email = request.email().trim();
219	        if (clients.existsByEmailIgnoreCase(email)) {
220	            throw emailTaken();
221	        }
222	        try {
223	            return respond(clients.saveAndFlush(
224	                    new Client(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber())));
225	        } catch (DataIntegrityViolationException e) {
226	            // Lost a race with a concurrent add of the same email; the unique constraint caught it.
227	            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
228	                throw emailTaken();
229	            }
230	            throw e;
231	        }
232	    }
233	
234	    /**
235	     * Corrects a client's name, email, phone number and tax number; the email, once trimmed, must not belong to another client.
236	     * The change is recorded in the audit log.
237	     */
238	    @Transactional
239	    public ClientResponse update(Long id, ClientRequest request) {
240	        Client client = find(id);
241	        String email = request.email().trim();
242	        if (clients.existsByEmailIgnoreCaseAndIdNot(email, id)) {
243	            throw emailTaken();
244	        }
245	        client.rename(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber());
246	        try {
247	            clients.flush();
248	        } catch (DataIntegrityViolationException e) {
249	            // Lost a race with a concurrent change to the same email; the unique constraint caught it.
250	            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
251	                throw emailTaken();
252	            }
253	            throw e;
254	        }
255	        audit.record("CLIENT_UPDATED id=" + id);
256	        return respond(client);
257	    }
258	
259	    /** Changes the currency a client is billed in, recording the change in the audit log. */
260	    @Transactional
261	    public ClientResponse changeCurrency(Long id, Currency currency) {
262	        Client client = find(id);
263	        if (client.getCurrency() != currency) {
264	            client.setCurrency(currency);
265	            clients.flush();
266	            audit.record("CLIENT_CURRENCY_CHANGED id=" + id + " currency=" + currency);
267	        }
268	        return respond(client);
269	    }
270	
271	    private static ResponseStatusException emailTaken() {
272	        return new ResponseStatusException(HttpStatus.CONFLICT, "A client with this email already exists");
273	    }
274	
275	    /**
276	     * Archives a client: it drops off the client list and search but is kept, with its projects and
277	     * contacts, and the archiving is recorded in the audit log.
278	     */
279	    @Transactional
280	    public ClientResponse archive(Long id) {
281	        Client client = find(id);
282	        if (!client.isArchived()) {
283	            client.setArchived(true);
284	            clients.flush();
285	            audit.record("CLIENT_ARCHIVED id=" + id);
286	        }
287	        return respond(client);
288	    }
289	
290	    /** Brings an archived client back onto the client list, recording it in the audit log. */
291	    @Transactional
292	    public ClientResponse restore(Long id) {
293	        Client client = find(id);
294	        if (client.isArchived()) {
295	            client.setArchived(false);
296	            clients.flush();
297	            audit.record("CLIENT_RESTORED id=" + id);
298	        }
299	        return respond(client);
300	    }
301	
302	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
303	
304	    /** The given clients, each with what they still owe. */
305	    @Transactional(readOnly = true)
306	    public List<ClientResponse> respond(List<Client> found) {
307	        Map<Long, BigDecimal> owed = outstandingByClient();
308	        return found.stream().map(c -> ClientResponse.from(c, owed.getOrDefault(c.getId(), ZERO))).toList();
309	    }
310	
311	    /**
312	     * The clients who owe the most, largest debt first (ties by id), at most {@code limit} of them.
313	     * Clients owing nothing are left out.
314	     */
315	    @Transactional(readOnly = true)
316	    public List<ClientResponse> topByOutstanding(int limit) {
317	        Map<Long, BigDecimal> owed = outstandingByClient();
318	        owed.values().removeIf(amount -> amount.signum() <= 0);
319	        List<Long> top = owed.entrySet().stream()
320	                .sorted(Map.Entry.<Long, BigDecimal>comparingByValue().reversed()
321	                        .thenComparing(Map.Entry.comparingByKey()))
322	                .limit(limit)
323	                .map(Map.Entry::getKey)
324	                .toList();
325	        Map<Long, Client> found = new HashMap<>();
326	        clients.findAllById(top).forEach(c -> found.put(c.getId(), c));
327	        return top.stream().map(id -> ClientResponse.from(found.get(id), owed.get(id))).toList();
328	    }
329	
330	    /**
331	     * What is still owed in each currency, each client's debt counted in their own currency; amounts
332	     * in different currencies are never added together. Currencies nothing is owed in are left out.
333	     */
334	    @Transactional(readOnly = true)
335	    public Map<Currency, BigDecimal> outstandingByCurrency() {
336	        Map<Long, BigDecimal> owed = outstandingByClient();
337	        Map<Currency, BigDecimal> totals = new EnumMap<>(Currency.class);
338	        clients.findAllById(owed.keySet())
339	                .forEach(c -> totals.merge(c.getCurrency(), owed.get(c.getId()), BigDecimal::add));
340	        totals.values().removeIf(amount -> amount.signum() == 0);
341	        return totals;
342	    }
343	
344	    private ClientResponse respond(Client client) {
345	        return ClientResponse.from(client, outstandingByClient().getOrDefault(client.getId(), ZERO));
346	    }
347	
348	    /**
349	     * What each client still owes: what is left to pay on their sent invoices that are not yet fully
350	     * paid. Clients owing nothing are left out.
351	     */
352	    private Map<Long, BigDecimal> outstandingByClient() {
353	        List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
354	        Map<Long, BigDecimal> owed = new HashMap<>();
355	        invoices.sumAmountByStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(), t.getTotal(),
356	                BigDecimal::add));
357	        payments.sumAmountByInvoiceStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(),
358	                t.getTotal().negate(), BigDecimal::add));
359	        owed.replaceAll((id, amount) -> amount.setScale(2, RoundingMode.HALF_UP));
360	        return owed;
361	    }
362	
363	    private Client find(Long id) {
364	        return clients.findById(id)
365	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
366	    }
367	}
