392	/**
393	 * An invoice raised against a project. It is built from line items, and can take a percentage off
394	 * their sum as a discount, then add a percentage sales tax on what is left of the taxable lines only
395	 * (tax-free lines are never taxed), and optionally a second tax (a levy) worked out on the same taxable base;
396	 * its stored amount is always that subtotal less the discount plus the tax plus the levy.
397	 */
398	@Entity
399	@Table(name = "invoice")
400	public class Invoice {
401	
402	    @Id
403	    @GeneratedValue(strategy = GenerationType.IDENTITY)
404	    private Long id;
405	
406	    @ManyToOne(fetch = FetchType.LAZY, optional = false)
407	    @JoinColumn(name = "project_id", nullable = false)
408	    private Project project;
409	
410	    @Column(nullable = false, precision = 12, scale = 2)
411	    private BigDecimal amount = BigDecimal.ZERO.setScale(2);
412	
413	    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
414	    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);
415	
416	    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
417	    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);
418	
419	    @Column(name = "levy_pct", nullable = false, precision = 5, scale = 2)
420	    private BigDecimal levyPct = BigDecimal.ZERO.setScale(2);
421	
422	    @Enumerated(EnumType.STRING)
423	    @Column(nullable = false, length = 16)
424	    private InvoiceStatus status = InvoiceStatus.DRAFT;
425	
426	    @Column(name = "issued_date", nullable = false)
427	    private LocalDate issuedDate;
428	
429	    @Column(name = "due_date", nullable = false)
430	    private LocalDate dueDate;
431	
432	    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
433	    @OrderBy("id")
434	    private List<InvoiceLineItem> lineItems = new ArrayList<>();
435	
436	    protected Invoice() {
437	    }
438	
439	    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
440	        this.project = project;
441	        this.issuedDate = issuedDate;
442	        this.dueDate = dueDate;
443	    }
444	
445	    public Long getId() {
446	        return id;
447	    }
448	
449	    public Project getProject() {
450	        return project;
451	    }
452	
453	    public BigDecimal getAmount() {
454	        return amount;
455	    }
456	
457	    /** The percentage taken off the subtotal; zero when there is no discount. */
458	    public BigDecimal getDiscountPct() {
459	        return discountPct;
460	    }
461	
462	    /** What the line items add up to, before any discount. */
463	    public BigDecimal getSubtotal() {
464	        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add)
465	                .setScale(2, RoundingMode.HALF_UP);
466	    }
467	
468	    /** How much the discount takes off the subtotal, to the cent. */
469	    public BigDecimal getDiscount() {
470	        return discountOn(getSubtotal());
471	    }
472	
473	    /** The sales tax percentage added after the discount; zero when there is no tax. */
474	    public BigDecimal getTaxPct() {
475	        return taxPct;
476	    }
477	
478	    /**
479	     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
480	     * taken off them, to the cent.
481	     */
482	    public BigDecimal getTaxableBase() {
483	        BigDecimal taxable = lineItems.stream().filter(l -> !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
484	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2, RoundingMode.HALF_UP);
485	        return taxable.subtract(discountOn(taxable));
486	    }
487	
488	    /** How much sales tax is added on the taxable base, to the cent. */
489	    public BigDecimal getTax() {
490	        return taxOn(getTaxableBase());
491	    }
492	
493	    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
494	    public BigDecimal getLevyPct() {
495	        return levyPct;
496	    }
497	
498	    /** How much levy is added on the taxable base, to the cent. */
499	    public BigDecimal getLevy() {
500	        return percentOf(getTaxableBase(), levyPct);
501	    }
502	
503	    public InvoiceStatus getStatus() {
504	        return status;
505	    }
506	
507	    public LocalDate getIssuedDate() {
508	        return issuedDate;
509	    }
510	
511	    public LocalDate getDueDate() {
512	        return dueDate;
513	    }
514	
515	    public List<InvoiceLineItem> getLineItems() {
516	        return List.copyOf(lineItems);
517	    }
518	
519	    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
520	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
521	        return addLineItem(description, qty, unit, unitPrice, false);
522	    }
523	
524	    /** Adds a line, taxable or tax-free, to this invoice and reworks its amount to include what the line charges. */
525	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
526	            boolean taxExempt) {
527	        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt);
528	        lineItems.add(item);
529	        recalculateAmount();
530	        return item;
531	    }
532	
533	    /** Changes one of this invoice's lines and reworks its amount to match. */
534	    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
535	            BigDecimal unitPrice, boolean taxExempt) {
536	        item.update(description, qty, unit, unitPrice, taxExempt);
537	        recalculateAmount();
538	    }
539	
540	    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
541	    public void removeLineItem(InvoiceLineItem item) {
542	        lineItems.remove(item);
543	        recalculateAmount();
544	    }
545	
546	    /** The line on this invoice with the given id, if there is one. */
547	    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
548	        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
549	    }
550	
551	    /** Sets the percentage taken off this invoice and reworks its amount to match. */
552	    public void applyDiscount(BigDecimal discountPct) {
553	        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
554	        recalculateAmount();
555	    }
556	
557	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
558	    public void applyTax(BigDecimal taxPct) {
559	        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
560	        recalculateAmount();
561	    }
562	
563	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
564	    public void applyLevy(BigDecimal levyPct) {
565	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
566	        recalculateAmount();
567	    }
568	
569	    private BigDecimal discountOn(BigDecimal subtotal) {
570	        return subtotal.multiply(discountPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
571	    }
572	
573	    private BigDecimal taxOn(BigDecimal taxableBase) {
574	        return percentOf(taxableBase, taxPct);
575	    }
576	
577	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
578	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
579	    }
580	
581	    private void recalculateAmount() {
582	        BigDecimal subtotal = getSubtotal();
583	        BigDecimal discounted = subtotal.subtract(discountOn(subtotal));
584	        this.amount = discounted.add(getTax()).add(getLevy());
585	    }
586	
587	    /** Marks this invoice as sent to the client. */
588	    public void markSent() {
589	        this.status = InvoiceStatus.SENT;
590	    }
591	
592	    /** Cancels this invoice, so it is no longer owed. */
593	    public void markVoid() {
594	        this.status = InvoiceStatus.VOID;
595	    }
596	
597	    /** What is left to pay on this invoice given the total paid against it; nothing once it is void. */
598	    public BigDecimal amountDue(BigDecimal paid) {
599	        return status == InvoiceStatus.VOID ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid);
600	    }
601	
602	    /**
603	     * Works out this sent invoice's status from the total paid against it: PAID once the payments
604	     * cover the amount, PARTIAL once something has been paid, otherwise still SENT.
605	     */
606	    public void applyPaidTotal(BigDecimal paid) {
607	        if (status == InvoiceStatus.DRAFT || status == InvoiceStatus.VOID) {
608	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be paid");
609	        }
610	        if (paid.compareTo(amount) >= 0) {
611	            this.status = InvoiceStatus.PAID;
612	        } else if (paid.signum() > 0) {
613	            this.status = InvoiceStatus.PARTIAL;
614	        } else {
615	            this.status = InvoiceStatus.SENT;
616	        }
617	    }
618	}
