708	    @Transactional
709	    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
710	        Project project = projects.findById(projectId)
711	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
712	        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
713	        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
714	        if (due.isBefore(issued)) {
715	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
716	        }
717	        Invoice invoice = new Invoice(project, issued, due);
718	        if (request.amount() != null) {
719	            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, null, request.amount());
720	        }
721	        invoice.applyTax(request.taxPct() != null ? request.taxPct() : settings.defaultTaxPct());
722	        Invoice saved = invoices.save(invoice);
723	        return InvoiceResponse.from(saved, BigDecimal.ZERO);
724	    }
725	
726	    /** A single invoice with its line items. */
727	    @Transactional(readOnly = true)
728	    public InvoiceDetailResponse get(Long projectId, Long invoiceId) {
729	        return InvoiceDetailResponse.from(find(projectId, invoiceId));
730	    }
731	
732	    /** Adds a line item to a draft invoice and reworks the invoice amount to match. */
733	    @Transactional
734	    public InvoiceDetailResponse addLineItem(Long projectId, Long invoiceId, LineItemRequest request) {
735	        Invoice invoice = findDraft(projectId, invoiceId);
736	        invoice.addLineItem(request.description().strip(), request.qty(), request.normalizedUnit(), request.unitPrice(),
737	                request.exempt());
738	        invoices.flush();
739	        return InvoiceDetailResponse.from(invoice);
740	    }
741	
742	    /** Changes a line item on a draft invoice and reworks the invoice amount to match. */
743	    @Transactional
744	    public InvoiceDetailResponse updateLineItem(Long projectId, Long invoiceId, Long lineItemId,
745	            LineItemRequest request) {
746	        Invoice invoice = findDraft(projectId, invoiceId);
747	        InvoiceLineItem item = findLineItem(invoice, lineItemId);
748	        invoice.updateLineItem(item, request.description().strip(), request.qty(), request.normalizedUnit(),
749	                request.unitPrice(), request.exempt());
750	        invoices.flush();
751	        return InvoiceDetailResponse.from(invoice);
752	    }
753	
754	    /** Removes a line item from a draft invoice and reworks the invoice amount to match. */
755	    @Transactional
756	    public InvoiceDetailResponse removeLineItem(Long projectId, Long invoiceId, Long lineItemId) {
757	        Invoice invoice = findDraft(projectId, invoiceId);
758	        invoice.removeLineItem(findLineItem(invoice, lineItemId));
759	        invoices.flush();
760	        return InvoiceDetailResponse.from(invoice);
761	    }
762	
763	    /** Sets the percentage discount on a draft invoice and reworks the invoice amount to match. */
764	    @Transactional
765	    public InvoiceDetailResponse applyDiscount(Long projectId, Long invoiceId, DiscountRequest request) {
766	        Invoice invoice = findDraft(projectId, invoiceId);
767	        invoice.applyDiscount(request.discountPct());
768	        invoices.flush();
769	        return InvoiceDetailResponse.from(invoice);
770	    }
771	
772	    /** Sets the sales tax percentage on a draft invoice and reworks the invoice amount to match. */
773	    @Transactional
774	    public InvoiceDetailResponse applyTax(Long projectId, Long invoiceId, TaxRequest request) {
775	        Invoice invoice = findDraft(projectId, invoiceId);
776	        invoice.applyTax(request.taxPct());
777	        invoices.flush();
778	        return InvoiceDetailResponse.from(invoice);
779	    }
780	
781	    /** Sets the levy (second tax) percentage on a draft invoice and reworks the invoice amount to match. */
782	    @Transactional
783	    public InvoiceDetailResponse applyLevy(Long projectId, Long invoiceId, LevyRequest request) {
784	        Invoice invoice = findDraft(projectId, invoiceId);
785	        invoice.applyLevy(request.levyPct());
786	        invoices.flush();
787	        return InvoiceDetailResponse.from(invoice);
788	    }
789	
790	    /** Sends a draft invoice and records the sending in the audit log. */
791	    @Transactional
792	    public InvoiceResponse send(Long projectId, Long invoiceId) {
793	        Invoice invoice = find(projectId, invoiceId);
794	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
795	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
796	        }
797	        if (invoice.getAmount().signum() == 0) {
798	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
799	        }
800	        invoice.markSent();
801	        invoices.flush();
802	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
803	        return toResponse(invoice);
804	    }
805	
806	    /**
807	     * Cancels an invoice sent by mistake, so it no longer counts toward what is owed, and records the
808	     * cancellation in the audit log. Only a sent invoice with nothing yet paid against it can be voided.
809	     */
810	    @Transactional
811	    public InvoiceResponse cancel(Long projectId, Long invoiceId) {
812	        Invoice invoice = find(projectId, invoiceId);
813	        if (invoice.getStatus() != InvoiceStatus.SENT) {
814	            throw new ResponseStatusException(HttpStatus.CONFLICT,
815	                    "Only a sent invoice with no payments recorded can be cancelled");
816	        }
817	        invoice.markVoid();
818	        invoices.flush();
819	        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
820	        return toResponse(invoice);
821	    }
822	
823	    private InvoiceResponse toResponse(Invoice invoice) {
824	        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()));
825	    }
826	
827	    private Invoice find(Long projectId, Long invoiceId) {
828	        return invoices.findById(invoiceId)
829	                .filter(i -> i.getProject().getId().equals(projectId))
830	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
831	    }
832	
