834	        Invoice invoice = find(projectId, invoiceId);
835	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
836	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be changed");
837	        }
838	        return invoice;
839	    }
840	
841	    private static InvoiceLineItem findLineItem(Invoice invoice, Long lineItemId) {
842	        return invoice.findLineItem(lineItemId)
843	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown line item"));
844	    }
845	}
