package net.officefloor.hq.app.client;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import net.officefloor.hq.app.contact.Contact;

/** A client of the office. */
@Entity
@Table(name = "client")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String email;

    /** A number to reach the client on; none when not known. */
    private String phone;

    /** The client's tax registration number; none when they are not tax registered. */
    private String taxNumber;

    private boolean archived;

    /** The currency the client is billed in; all of their money is in it. */
    @Enumerated(EnumType.STRING)
    private Currency currency = Currency.USD;

    /** The client's main contact, one of its own contacts; none until one is chosen. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "primary_contact_id")
    private Contact primaryContact;

    protected Client() {
    }

    public Client(String name, String email, String phone, String taxNumber) {
        this.name = name;
        this.email = email;
        this.phone = phone;
        this.taxNumber = taxNumber;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public String getPhone() {
        return phone;
    }

    public String getTaxNumber() {
        return taxNumber;
    }

    /** Corrects the client's name, email, phone number and tax number. */
    public void rename(String name, String email, String phone, String taxNumber) {
        this.name = name;
        this.email = email;
        this.phone = phone;
        this.taxNumber = taxNumber;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }

    public Currency getCurrency() {
        return currency;
    }

    public void setCurrency(Currency currency) {
        this.currency = currency;
    }

    public Contact getPrimaryContact() {
        return primaryContact;
    }

    public void setPrimaryContact(Contact primaryContact) {
        this.primaryContact = primaryContact;
    }
}
package net.officefloor.hq.app.client;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/** Payload to create a client, or to correct an existing client's name, email, phone number and tax number. */
public record ClientRequest(
        @NotBlank @Size(max = 255) String name,
        @NotBlank @Email(regexp = ClientRequest.EMAIL_PATTERN) @Size(max = 255) String email,
        @Size(max = 50) String phone,
        @Size(max = 50) String taxNumber) {

    /** Requires a dotted domain, which plain {@code @Email} does not (it accepts {@code a@b}). */
    public static final String EMAIL_PATTERN = "^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$";

    /** The phone number trimmed, or null when none was given. */
    public String trimmedPhone() {
        return phone == null || phone.isBlank() ? null : phone.trim();
    }

    /** The tax number trimmed, or null when the client is not tax registered. */
    public String trimmedTaxNumber() {
        return taxNumber == null || taxNumber.isBlank() ? null : taxNumber.trim();
    }
}
package net.officefloor.hq.app.client;

import java.math.BigDecimal;
import net.officefloor.hq.app.contact.Contact;

public record ClientResponse(Long id, String name, String email, String phone, String taxNumber, boolean archived, PrimaryContact primaryContact,
        Currency currency, BigDecimal outstanding) {

    /** Who the client's main contact is; null when none has been chosen. */
    public record PrimaryContact(Long id, String name) {
    }

    /** A client with what they still owe, in their currency: what is left to pay on their sent, not yet fully paid invoices. */
    public static ClientResponse from(Client client, BigDecimal outstanding) {
        Contact primary = client.getPrimaryContact();
        return new ClientResponse(client.getId(), client.getName(), client.getEmail(), client.getPhone(), client.getTaxNumber(), client.isArchived(),
                primary == null ? null : new PrimaryContact(primary.getId(), primary.getName()),
                client.getCurrency(), outstanding);
    }
}
package net.officefloor.hq.app.client;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.contact.ContactRepository;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import net.officefloor.hq.app.payment.PaymentRepository;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClientService {

    private final ClientRepository clients;
    private final ProjectRepository projects;
    private final ContactRepository contacts;
    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final Audit audit;

    public ClientService(ClientRepository clients, ProjectRepository projects, ContactRepository contacts,
            InvoiceRepository invoices, PaymentRepository payments, Audit audit) {
        this.clients = clients;
        this.projects = projects;
        this.contacts = contacts;
        this.invoices = invoices;
        this.payments = payments;
        this.audit = audit;
    }

    /** The clients, leaving out archived ones unless they are asked for. */
    @Transactional(readOnly = true)
    public List<ClientResponse> list(boolean includeArchived) {
        List<Client> found = includeArchived ? clients.findAll(Sort.by("id")) : clients.findByArchivedFalseOrderById();
        return respond(found);
    }

    @Transactional(readOnly = true)
    public ClientResponse get(Long id) {
        return respond(find(id));
    }

    /** At-a-glance counts of what one client has. */
    @Transactional(readOnly = true)
    public ClientSummaryResponse summary(Long id) {
        if (!clients.existsById(id)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        return new ClientSummaryResponse(projects.countByClientId(id), contacts.countByClientId(id));
    }

    /** Adds a client; its email, once trimmed, must not already belong to another client. */
    @Transactional
    public ClientResponse create(ClientRequest request) {
        String email = request.email().trim();
        if (clients.existsByEmailIgnoreCase(email)) {
            throw emailTaken();
        }
        try {
            return respond(clients.saveAndFlush(
                    new Client(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber())));
        } catch (DataIntegrityViolationException e) {
            // Lost a race with a concurrent add of the same email; the unique constraint caught it.
            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
                throw emailTaken();
            }
            throw e;
        }
    }

    /**
     * Corrects a client's name, email, phone number and tax number; the email, once trimmed, must not belong to another client.
     * The change is recorded in the audit log.
     */
    @Transactional
    public ClientResponse update(Long id, ClientRequest request) {
        Client client = find(id);
        String email = request.email().trim();
        if (clients.existsByEmailIgnoreCaseAndIdNot(email, id)) {
            throw emailTaken();
        }
        client.rename(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber());
        try {
            clients.flush();
        } catch (DataIntegrityViolationException e) {
            // Lost a race with a concurrent change to the same email; the unique constraint caught it.
            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
                throw emailTaken();
            }
            throw e;
        }
        audit.record("CLIENT_UPDATED id=" + id);
        return respond(client);
    }

    /** Changes the currency a client is billed in, recording the change in the audit log. */
    @Transactional
    public ClientResponse changeCurrency(Long id, Currency currency) {
        Client client = find(id);
        if (client.getCurrency() != currency) {
            client.setCurrency(currency);
            clients.flush();
            audit.record("CLIENT_CURRENCY_CHANGED id=" + id + " currency=" + currency);
        }
        return respond(client);
    }

    private static ResponseStatusException emailTaken() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "A client with this email already exists");
    }

    /**
     * Archives a client: it drops off the client list and search but is kept, with its projects and
     * contacts, and the archiving is recorded in the audit log.
     */
    @Transactional
    public ClientResponse archive(Long id) {
        Client client = find(id);
        if (!client.isArchived()) {
            client.setArchived(true);
            clients.flush();
            audit.record("CLIENT_ARCHIVED id=" + id);
        }
        return respond(client);
    }

    /** Brings an archived client back onto the client list, recording it in the audit log. */
    @Transactional
    public ClientResponse restore(Long id) {
        Client client = find(id);
        if (client.isArchived()) {
            client.setArchived(false);
            clients.flush();
            audit.record("CLIENT_RESTORED id=" + id);
        }
        return respond(client);
    }

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    /** The given clients, each with what they still owe. */
    @Transactional(readOnly = true)
    public List<ClientResponse> respond(List<Client> found) {
        Map<Long, BigDecimal> owed = outstandingByClient();
        return found.stream().map(c -> ClientResponse.from(c, owed.getOrDefault(c.getId(), ZERO))).toList();
    }

    /**
     * The clients who owe the most, largest debt first (ties by id), at most {@code limit} of them.
     * Clients owing nothing are left out.
     */
    @Transactional(readOnly = true)
    public List<ClientResponse> topByOutstanding(int limit) {
        Map<Long, BigDecimal> owed = outstandingByClient();
        owed.values().removeIf(amount -> amount.signum() <= 0);
        List<Long> top = owed.entrySet().stream()
                .sorted(Map.Entry.<Long, BigDecimal>comparingByValue().reversed()
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(limit)
                .map(Map.Entry::getKey)
                .toList();
        Map<Long, Client> found = new HashMap<>();
        clients.findAllById(top).forEach(c -> found.put(c.getId(), c));
        return top.stream().map(id -> ClientResponse.from(found.get(id), owed.get(id))).toList();
    }

    /**
     * What is still owed in each currency, each client's debt counted in their own currency; amounts
     * in different currencies are never added together. Currencies nothing is owed in are left out.
     */
    @Transactional(readOnly = true)
    public Map<Currency, BigDecimal> outstandingByCurrency() {
        Map<Long, BigDecimal> owed = outstandingByClient();
        Map<Currency, BigDecimal> totals = new EnumMap<>(Currency.class);
        clients.findAllById(owed.keySet())
                .forEach(c -> totals.merge(c.getCurrency(), owed.get(c.getId()), BigDecimal::add));
        totals.values().removeIf(amount -> amount.signum() == 0);
        return totals;
    }

    private ClientResponse respond(Client client) {
        return ClientResponse.from(client, outstandingByClient().getOrDefault(client.getId(), ZERO));
    }

    /**
     * What each client still owes: what is left to pay on their sent invoices that are not yet fully
     * paid. Clients owing nothing are left out.
     */
    private Map<Long, BigDecimal> outstandingByClient() {
        List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
        Map<Long, BigDecimal> owed = new HashMap<>();
        invoices.sumAmountByStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(), t.getTotal(),
                BigDecimal::add));
        payments.sumAmountByInvoiceStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(),
                t.getTotal().negate(), BigDecimal::add));
        owed.replaceAll((id, amount) -> amount.setScale(2, RoundingMode.HALF_UP));
        return owed;
    }

    private Client find(Long id) {
        return clients.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
    }
}
package net.officefloor.hq.app.invoice;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.project.Project;

/**
 * An invoice raised against a project. It is built from line items, and can take a percentage off
 * their sum as a discount, then add a percentage sales tax on what is left of the taxable lines only
 * (tax-free lines are never taxed), and optionally a second tax (a levy) worked out on the same taxable base;
 * its stored amount is always that subtotal less the discount plus the tax plus the levy.
 */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount = BigDecimal.ZERO.setScale(2);

    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);

    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);

    @Column(name = "levy_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal levyPct = BigDecimal.ZERO.setScale(2);

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private InvoiceStatus status = InvoiceStatus.DRAFT;

    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
    @OrderBy("id")
    private List<InvoiceLineItem> lineItems = new ArrayList<>();

    protected Invoice() {
    }

    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
        this.project = project;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /** The percentage taken off the subtotal; zero when there is no discount. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** What the line items add up to, before any discount. */
    public BigDecimal getSubtotal() {
        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
    }

    /** How much the discount takes off the subtotal, to the cent. */
    public BigDecimal getDiscount() {
        return discountOn(getSubtotal());
    }

    /** The sales tax percentage added after the discount; zero when there is no tax. */
    public BigDecimal getTaxPct() {
        return taxPct;
    }

    /**
     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
     * taken off them, to the cent.
     */
    public BigDecimal getTaxableBase() {
        BigDecimal taxable = lineItems.stream().filter(l -> !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2, RoundingMode.HALF_UP);
        return taxable.subtract(discountOn(taxable));
    }

    /** How much sales tax is added on the taxable base, to the cent. */
    public BigDecimal getTax() {
        return taxOn(getTaxableBase());
    }

    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
    public BigDecimal getLevyPct() {
        return levyPct;
    }

    /** How much levy is added on the taxable base, to the cent. */
    public BigDecimal getLevy() {
        return percentOf(getTaxableBase(), levyPct);
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    public List<InvoiceLineItem> getLineItems() {
        return List.copyOf(lineItems);
    }

    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
        return addLineItem(description, qty, unit, unitPrice, false);
    }

    /** Adds a line, taxable or tax-free, to this invoice and reworks its amount to include what the line charges. */
    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
            boolean taxExempt) {
        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt);
        lineItems.add(item);
        recalculateAmount();
        return item;
    }

    /** Changes one of this invoice's lines and reworks its amount to match. */
    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
            BigDecimal unitPrice, boolean taxExempt) {
        item.update(description, qty, unit, unitPrice, taxExempt);
        recalculateAmount();
    }

    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
    public void removeLineItem(InvoiceLineItem item) {
        lineItems.remove(item);
        recalculateAmount();
    }

    /** The line on this invoice with the given id, if there is one. */
    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
    }

    /** Sets the percentage taken off this invoice and reworks its amount to match. */
    public void applyDiscount(BigDecimal discountPct) {
        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
    public void applyTax(BigDecimal taxPct) {
        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
    public void applyLevy(BigDecimal levyPct) {
        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    private BigDecimal discountOn(BigDecimal subtotal) {
        return subtotal.multiply(discountPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
    }

    private BigDecimal taxOn(BigDecimal taxableBase) {
        return percentOf(taxableBase, taxPct);
    }

    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
    }

    private void recalculateAmount() {
        BigDecimal subtotal = getSubtotal();
        BigDecimal discounted = subtotal.subtract(discountOn(subtotal));
        this.amount = discounted.add(getTax()).add(getLevy());
    }

    /** Marks this invoice as sent to the client. */
    public void markSent() {
        this.status = InvoiceStatus.SENT;
    }

    /** Cancels this invoice, so it is no longer owed. */
    public void markVoid() {
        this.status = InvoiceStatus.VOID;
    }

    /** What is left to pay on this invoice given the total paid against it; nothing once it is void. */
    public BigDecimal amountDue(BigDecimal paid) {
        return status == InvoiceStatus.VOID ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid);
    }

    /**
     * Works out this sent invoice's status from the total paid against it: PAID once the payments
     * cover the amount, PARTIAL once something has been paid, otherwise still SENT.
     */
    public void applyPaidTotal(BigDecimal paid) {
        if (status == InvoiceStatus.DRAFT || status == InvoiceStatus.VOID) {
            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be paid");
        }
        if (paid.compareTo(amount) >= 0) {
            this.status = InvoiceStatus.PAID;
        } else if (paid.signum() > 0) {
            this.status = InvoiceStatus.PARTIAL;
        } else {
            this.status = InvoiceStatus.SENT;
        }
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.payment.PaymentRepository;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import net.officefloor.hq.app.settings.SettingsService;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final ProjectRepository projects;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final SettingsService settings;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, PaymentRepository payments,
            ClientRepository clients, SettingsService settings, Audit audit) {
        this.invoices = invoices;
        this.projects = projects;
        this.clients = clients;
        this.payments = payments;
        this.settings = settings;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<InvoiceResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
        }
        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        return found.stream()
                .map(i -> InvoiceResponse.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
    }

    /**
     * A client's statement: every invoice across their projects with what is left to pay on each, and
     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
     * void invoices, as they have been cancelled.
     */
    @Transactional(readOnly = true)
    public ClientStatementResponse statementForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        List<ClientStatementResponse.Line> lines = found.stream()
                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines);
    }

    private Map<Long, BigDecimal> paidByInvoice(List<Invoice> found) {
        return found.isEmpty() ? Map.of()
                : payments.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
                        .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
                                PaymentRepository.InvoicePaidTotal::getPaid));
    }

    /**
     * One page of the invoices across all projects, with the name of the project each one is for,
     * narrowed to the given status when one is supplied. Pages are numbered from zero.
     */
    @Transactional(readOnly = true)
    public InvoicePageResponse listAll(InvoiceStatus status, int page, int size) {
        PageRequest request = PageRequest.of(page, size);
        Page<Invoice> found = status == null ? invoices.findPageWithProject(request)
                : invoices.findPageWithProjectByStatus(status, request);
        return InvoicePageResponse.from(found);
    }

    @Transactional
    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
        if (due.isBefore(issued)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
        }
        Invoice invoice = new Invoice(project, issued, due);
        if (request.amount() != null) {
            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, null, request.amount());
        }
        invoice.applyTax(request.taxPct() != null ? request.taxPct() : settings.defaultTaxPct());
        Invoice saved = invoices.save(invoice);
        return InvoiceResponse.from(saved, BigDecimal.ZERO);
    }

    /** A single invoice with its line items. */
    @Transactional(readOnly = true)
    public InvoiceDetailResponse get(Long projectId, Long invoiceId) {
        return InvoiceDetailResponse.from(find(projectId, invoiceId));
    }

    /** Adds a line item to a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse addLineItem(Long projectId, Long invoiceId, LineItemRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.addLineItem(request.description().strip(), request.qty(), request.normalizedUnit(), request.unitPrice(),
                request.exempt());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Changes a line item on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse updateLineItem(Long projectId, Long invoiceId, Long lineItemId,
            LineItemRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        InvoiceLineItem item = findLineItem(invoice, lineItemId);
        invoice.updateLineItem(item, request.description().strip(), request.qty(), request.normalizedUnit(),
                request.unitPrice(), request.exempt());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Removes a line item from a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse removeLineItem(Long projectId, Long invoiceId, Long lineItemId) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.removeLineItem(findLineItem(invoice, lineItemId));
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the percentage discount on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applyDiscount(Long projectId, Long invoiceId, DiscountRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyDiscount(request.discountPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the sales tax percentage on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applyTax(Long projectId, Long invoiceId, TaxRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyTax(request.taxPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the levy (second tax) percentage on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applyLevy(Long projectId, Long invoiceId, LevyRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyLevy(request.levyPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sends a draft invoice and records the sending in the audit log. */
    @Transactional
    public InvoiceResponse send(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
        }
        if (invoice.getAmount().signum() == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
        }
        invoice.markSent();
        invoices.flush();
        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    /**
     * Cancels an invoice sent by mistake, so it no longer counts toward what is owed, and records the
     * cancellation in the audit log. Only a sent invoice with nothing yet paid against it can be voided.
     */
    @Transactional
    public InvoiceResponse cancel(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.SENT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "Only a sent invoice with no payments recorded can be cancelled");
        }
        invoice.markVoid();
        invoices.flush();
        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    private InvoiceResponse toResponse(Invoice invoice) {
        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()));
    }

    private Invoice find(Long projectId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }

    private Invoice findDraft(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be changed");
        }
        return invoice;
    }

    private static InvoiceLineItem findLineItem(Invoice invoice, Long lineItemId) {
        return invoice.findLineItem(lineItemId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown line item"));
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.client.Currency;

/**
 * A single invoice together with the line items it is built from: their subtotal, the percentage
 * discount and what it takes off, the sales tax percentage, the taxable base it is charged on (the
 * taxable lines after the discount) and what it adds, the levy (second tax) percentage and what it adds
 * on the same base, the amount owed including both taxes, and the
 * client's tax number (null when the client is not tax registered).
 */
public record InvoiceDetailResponse(Long id, Long projectId, Currency currency, BigDecimal amount, BigDecimal subtotal,
        BigDecimal discountPct, BigDecimal discount, BigDecimal taxPct, BigDecimal taxableBase, BigDecimal tax,
        BigDecimal levyPct, BigDecimal levy, InvoiceStatus status, LocalDate issuedDate,
        LocalDate dueDate, List<LineItemResponse> lineItems, String clientTaxNumber) {

    static InvoiceDetailResponse from(Invoice invoice) {
        return new InvoiceDetailResponse(invoice.getId(), invoice.getProject().getId(),
                invoice.getProject().getClient().getCurrency(), invoice.getAmount(),
                invoice.getSubtotal(), invoice.getDiscountPct(), invoice.getDiscount(),
                invoice.getTaxPct(), invoice.getTaxableBase(), invoice.getTax(),
                invoice.getLevyPct(), invoice.getLevy(),
                invoice.getStatus(), invoice.getIssuedDate(), invoice.getDueDate(),
                invoice.getLineItems().stream().map(LineItemResponse::from).toList(),
                invoice.getProject().getClient().getTaxNumber());
    }
}

